INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.105.0',
  '2026-09-29',
  'Пульт ТВ: кадры из фильма в «Инфо» и список фоновых задач',
  E'Постер показывает, как фильм продавали, а кадры — как он выглядит. Теперь под описанием в «Инфо» появилась полоса кадров: агент берёт десяток из середины фильма, обходя заставку, титры и затемнения между сценами. Кадр открывается на весь экран и листается стрелками, как снимки в «Фото».\n\nУ сериала кадры общие на весь сериал — по одному из десятка случайных серий: сотня картинок с каждой серии никому не нужна.\n\nЗапустить сборку можно на всю медиатеку сразу (где кадров ещё нет), только на фильмы или на один фильм или сериал — кнопка «🎞» у строки в админке. Там же свои кадры: снять с нужного места серии, загрузить картинку с компьютера, сделать кадр обложкой плитки.\n\nИ появилась вкладка «Задачи»: видно, что агент делает прямо сейчас, сколько уже сделано и что получилось по каждому фильму, а работу можно остановить. Поиск заставки по звуку переехал в тот же список.',
  E'media-agent: tasks.go — общий список фоновых задач. Одна задача за раз (ffmpeg и чтение с внешнего диска отбирают силы у просмотра на той же машине), последние 20 в памяти, у каждой стадия, счётчик и отчёт строками; GET /api/admin/tasks, POST /api/admin/tasks/{id}/stop. Поля задачи лежат под замком отдельной структурой taskView — возвращать структуру с mutex по значению нельзя (go vet ловит).\n\nframes.go: кадры для «Инфо». Точки съёмки — между 8 % и 92 % длительности со случайным сдвигом внутри шага, у сериала — по кадру из десятка случайных серий (videosUnder по сезонам, shuffle). Кадр вынимает ffmpeg -ss … -frames:v 1 масштабом 960 по ширине; средняя яркость считается по уменьшенной копии (decodeFit 64×64), тёмный кадр — ещё две попытки со сдвигом 3 % длительности. Хранение — кэш агента frames/<id>/: auto-NN.jpg собираются заново при пересборке, own-*.jpg добавлены руками и не трогаются; список отдаёт свои первыми. moveFrames в renamePath, рядом с moveMarks.\n\nAPI: GET /api/frames?id= (ссылки подписаны, как постеры) и GET /frame/{id}/{name}?k=; админские POST /api/admin/frames/scan {scope: all|films|item, id, redo}, /add {file, at}, /delete {id, name?}, /cover {id, name}; загрузка своей картинки — target=frame у чанкового аплоада.\n\nscan.go: собственный scanJob выброшен, поиск заставки запускается через startTask, отчёт по сериям идёт строками задачи.\n\nplayer.html: полоса кадров в карточке «Инфо»; кадр открывается через существующий просмотрщик — на стек экранов кладётся синтетический экран «photos» с кадрами вместо снимков, поэтому полный экран, листание и «Назад» работают без нового кода. В админке вкладка «Задачи» (запуск сборки, прогресс, отчёт, остановка) и экран «🎞» у строки: сетка кадров, пересборка, снимок с места серии на том же видео с шагами, что у отметок заставки, загрузка своего файла, «сделать обложкой».\n\nПроверено в браузере на настоящей библиотеке (Star Trek: Enterprise, 97 серий): сборка кадров сериала — 10 кадров из 10 разных серий за 3 с, свой кадр встаёт первым, удаление и пересборка не задевают свои, в «Инфо» полоса из 10 кадров открывается на весь экран и листается, вкладка «Задачи» показывает ход работы и отчёт. Тесты: план кадров для фильма и сериала, пропуск чёрного кадра, переезд кадров за переименованием, одна задача за раз и остановка.'
);
